def _unauthorized():
    return Response(
        "Autenticacao obrigatoria",
        401,
        {"WWW-Authenticate": 'Basic realm="ZAP Engine"'},
    )


@app.before_request
def proteger_painel():
    if request.path == "/api/health":
        return None

    if request.path == "/webhook":
        if WEBHOOK_SECRET:
            token = request.args.get("token") or request.headers.get("X-Webhook-Token", "")
            if not secrets.compare_digest(token, WEBHOOK_SECRET):
                return jsonify({"erro": "webhook nao autorizado"}), 401
        return None

    if PANEL_USERNAME and PANEL_PASSWORD:
        auth = request.authorization
        ok = (
            auth
            and secrets.compare_digest(auth.username or "", PANEL_USERNAME)
            and secrets.compare_digest(auth.password or "", PANEL_PASSWORD)
        )
        if not ok:
            return _unauthorized()
    return None


