    try:
        c = count_contacts_by_status()
    except: c = {}
    try:
        cps = list_campaigns()
    except: cps = []
    try:
        ab = get_antiban_settings()
    except: ab = {}
    try:
        hoje = get_today_count()
    except: hoje = 0
    try:
        hora = get_current_hour_count()
    except: hora = 0
