@app.route("/api/contatos/importar", methods=["POST"])
def api_importar():
    if "arquivo" not in request.files: return jsonify({"erro": "Nenhum arquivo"}), 400
    arq = request.files["arquivo"]
    if not arq.filename.lower().endswith((".csv",".xlsx",".xlsm")): return jsonify({"erro": "Use .csv ou .xlsx"}), 400
    import tempfile
    tmp_dir = tempfile.gettempdir()
    tmp = os.path.join(tmp_dir, secure_filename(arq.filename))
    arq.save(tmp)
    try:
        contatos = detectar_e_importar(tmp)
        ins, dup = insert_contacts_bulk(contatos)
        try: os.remove(tmp)
        except: pass
        return jsonify({"sucesso": True, "inseridos": ins, "duplicados": dup})
    except Exception as e: return jsonify({"erro": str(e)}), 500

