@app.route("/api/disparar", methods=["POST"])
def api_disparar():
    if campanha_ativa["rodando"]: return jsonify({"erro": "Campanha ja em andamento"}), 409
    d = request.json or {}
    msgs = [m.strip() for m in d.get("mensagens",[]) if m.strip()]
    if not msgs: return jsonify({"erro": "Informe pelo menos 1 mensagem"}), 400
    if not get_pending_contacts(): return jsonify({"erro": "Nenhum contato pendente"}), 400
    def rodar():
        campanha_ativa["rodando"] = True
        campanha_ativa["ultimo_erro"] = None
        try:
            executar_campanha(nome=d.get("nome","Campanha"), mensagens=msgs,
                lote_tamanho=int(d.get("lote_tamanho",10)),
                delay_lote_seg=int(d.get("delay_lote_seg",1800)),
                delay_msg_seg=int(d.get("delay_msg_seg",45)),
                media_url=d.get("media_url") or None,
                media_type=d.get("media_type") or None,
                daily_limit=int(d.get("daily_limit",0)),
                hourly_limit=int(d.get("hourly_limit",0) or 0) or None,
                delay_min_seg=int(d.get("delay_min_seg",0) or 0) or None,
                delay_max_seg=int(d.get("delay_max_seg",0) or 0) or None,
                pause_every=int(d.get("pause_every",0) or 0) or None,
                pause_min_seg=int(d.get("pause_min_seg",0) or 0) or None,
                pause_max_seg=int(d.get("pause_max_seg",0) or 0) or None,
                duplicate_cooldown_hours=int(d.get("duplicate_cooldown_hours",0) or 0) or None,
                control=campaign_control)
        except Exception as e:
            campanha_ativa["ultimo_erro"] = str(e)
            import traceback; traceback.print_exc()
        finally:
            campanha_ativa["rodando"] = False
    thread = threading.Thread(target=rodar, daemon=True)
    campanha_ativa["thread"] = thread
    thread.start()
    return jsonify({"sucesso": True, "mensagem": f"Campanha '{d.get('nome')}' iniciada!"})

