# â”€â”€ Teste rÃ¡pido â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
@app.route("/api/test-send", methods=["POST"])
def api_test_send():
    d = request.json or {}
    num = formatar_telefone(d.get("numero",""))
    txt = d.get("texto","Teste ZAP Engine âœ…")
    if not validar_telefone(num): return jsonify({"erro": "Numero invalido"}), 400
    try:
        estado = check_instance()
    except Exception as exc:
        return jsonify({"erro": f"Nao foi possivel verificar a instancia: {exc}"}), 500
    if estado.get("state") != "open":
        return jsonify({"erro": "WhatsApp nao esta conectado", "estado": estado}), 409
    validacao = resolve_whatsapp_number(num)
    if not (validacao.get("success") and validacao.get("exists")):
        return jsonify({
            "erro": "Nao foi possivel validar o numero no WhatsApp",
            "estado": estado,
            "validacao": validacao,
        }), 422
    destino = (validacao.get("jid") or "").replace("@s.whatsapp.net", "") or num
    resultado = send_text_message(destino, txt)
    rastreio = get_latest_outbound_by_phone(destino) or get_latest_outbound_by_phone(num)
    return jsonify({
        "numero_enviado": destino,
        "numero_original": num,
        "estado": estado,
        "validacao": validacao,
        "resultado": resultado,
        "rastreio": rastreio,
    })

