@app.route("/api/logs")
def api_logs():
    import glob
    log_dir = os.path.join(os.path.dirname(__file__), "..", "logs")
    arqs = sorted(glob.glob(os.path.join(log_dir, "*.log")))
    if not arqs: return jsonify({"linhas": []})
    with open(arqs[-1], encoding="utf-8") as f: linhas = f.readlines()
    return jsonify({"linhas": [l.strip() for l in linhas[-40:]]})

