# â”€â”€ Chat â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
@app.route("/api/chat/conversas")
def api_conversas():
    try:
        convs = fetch_conversations()
        # Busca nomes do banco de contatos
        conn = get_connection()
        contatos_db = conn.execute("SELECT telefone, nome FROM contacts").fetchall()
        conn.close()
        nomes_db = {}
        for c in contatos_db:
            if not c["nome"]: continue
            tel = c["telefone"]
            # Adiciona todas as variaÃ§Ãµes possÃ­veis do nÃºmero
            nomes_db[tel] = c["nome"]
            # Sem o 55
            sem55 = tel[2:] if tel.startswith("55") else tel
            nomes_db[sem55] = c["nome"]
            # Com 55
            nomes_db["55"+sem55] = c["nome"]
            # Remove o 9 extra (nÃºmeros antigos BR)
            if len(sem55) == 11 and sem55[2] == "9":
                sem9 = sem55[:2] + sem55[3:]
                nomes_db[sem9] = c["nome"]
                nomes_db["55"+sem9] = c["nome"]

        resultado = []
        for c in convs[:30]:
            num = c.get("numero","")
            # Tenta achar o nome no banco
            nome = nomes_db.get(num) or nomes_db.get("55"+num) or c.get("nome") or num
            resultado.append({"jid": c.get("id",""), "numero": num, "nome": nome, "nao_lidas": 0})
        return jsonify(resultado)
    except Exception as e:
        print(f"Erro conversas: {e}")
        return jsonify([])

@app.route("/api/chat/mensagens", methods=["POST"])
def api_mensagens():
    jid = (request.json or {}).get("jid","")
    # Busca todas as mensagens e filtra pelo JID
    from services.evolution_api import fetch_messages as fm_all
    msgs = fm_all(jid, 50)
    if not isinstance(msgs, list):
        msgs = []
    # Filtra apenas mensagens deste contato
    result = []
    for m in msgs:
        key = m.get("key", {})
        remote = key.get("remoteJid","")
        # Aceita apenas mensagens deste JID especÃ­fico
        if remote and remote != jid:
            continue
        c = m.get("message") or {}
        txt = (c.get("conversation") or
               c.get("extendedTextMessage",{}).get("text") or
               c.get("imageMessage",{}).get("caption") or
               "[mÃ­dia]")
        if not txt or txt == "[mÃ­dia]":
            continue
        ts = m.get("messageTimestamp", 0)
        if isinstance(ts, dict):
            ts = ts.get("low", 0)
        result.append({
            "de_mim": key.get("fromMe", False),
            "texto": txt,
            "hora": ts
        })
    result.sort(key=lambda x: x["hora"])
    return jsonify(result)

