@app.route("/api/ia/conversas")
def api_ia_conversas():
    from services.groq_ai import classificar_opcao_retorno, get_horas_reabertura, mensagem_assistente_eh_reabertura

    convs = []
    for conv in list_conversations_ai():
        item = dict(conv)
        try:
            hist = json.loads(item.get("historico_json", "[]") or "[]")
        except Exception:
            hist = []
        item["menu_reabertura"] = bool(mensagem_assistente_eh_reabertura(hist))
        item["opcao_ultima"] = ""
        item["ultimo_status"] = "IA"
        ultimo_user = ""
        for msg in reversed(hist):
            if not isinstance(msg, dict):
                continue
            if not ultimo_user and msg.get("role") == "user":
                ultimo_user = msg.get("content", "")
            if msg.get("role") == "assistant":
                if mensagem_assistente_eh_reabertura(hist):
                    item["ultimo_status"] = "Menu retorno"
                    item["opcao_ultima"] = classificar_opcao_retorno(ultimo_user) or ""
                elif item.get("modo_humano"):
                    item["ultimo_status"] = "Humano"
                break
        ultima_msg = item.get("ultima_msg", "")
        horas_inativo = 0.0
        if ultima_msg:
            try:
                dt_ultima = datetime.fromisoformat(str(ultima_msg).replace("T", " ").split(".")[0])
                horas_inativo = (datetime.now() - dt_ultima).total_seconds() / 3600
            except Exception:
                horas_inativo = 0.0
        item["horas_inativo"] = round(horas_inativo, 1)
        item["retornou"] = horas_inativo >= max(1, int(get_horas_reabertura(24))) and bool(hist)
        ultimo_envio = get_latest_outbound_by_phone(item.get("numero", ""))
        if ultimo_envio:
            item["ultimo_envio_status"] = ultimo_envio.get("provider_status") or "PENDING"
        else:
            item["ultimo_envio_status"] = ""
        convs.append(item)
    return jsonify(convs)

