@app.route("/api/ia/configurar-webhook", methods=["POST"])
def api_configurar_webhook():
    """Configura o webhook na Evolution API automaticamente."""
    import requests as req
    from config.settings import EVOLUTION_API_URL, INSTANCE_NAME, HEADERS
    d = request.json or {}
    default_url = (PUBLIC_BASE_URL.rstrip("/") + "/webhook") if PUBLIC_BASE_URL else "http://localhost:5000/webhook"
    webhook_url = d.get("webhook_url") or default_url
    if WEBHOOK_SECRET and "token=" not in webhook_url:
        sep = "&" if "?" in webhook_url else "?"
        webhook_url = webhook_url + sep + urlencode({"token": WEBHOOK_SECRET})
    payload = {"url": webhook_url, "webhook_by_events": False,
        "webhook_base64": False, "events": ["MESSAGES_UPSERT", "MESSAGES_UPDATE"]}
    try:
        r = req.post(f"{EVOLUTION_API_URL}/webhook/set/{INSTANCE_NAME}",
            json=payload, headers=HEADERS, timeout=10)
        return jsonify({"sucesso": True, "resposta": r.json()})
    except Exception as e:
        return jsonify({"erro": str(e)}), 500

def _normalizar_status_envio(valor: str) -> str:
    status = str(valor or "").strip().lower().replace(" ", "_")
    mapa = {
        "pending": "pending",
        "peding": "pending",
        "pnding": "pending",
        "server_ack": "server_ack",
        "delivered": "delivered",
        "delivery_ack": "delivered",
        "read": "read",
        "read_ack": "read",
        "failed": "failed",
        "error": "failed",
        "sent": "sent",
        "success": "sent",
    }
    return mapa.get(status, status or "unknown")


def _atualizar_status_rastreio(item: dict):
    if not isinstance(item, dict):
        return False
    key = item.get("key") or item.get("messageKey") or item.get("message", {}).get("key") or {}
    message_id = str(key.get("id") or item.get("id") or item.get("message_id") or "").strip()
    remote_jid = str(key.get("remoteJid") or item.get("remoteJid") or "").strip()
    status = (
        item.get("status")
        or item.get("messageStatus")
        or item.get("update", {}).get("status")
        or item.get("update", {}).get("messageStatus")
        or item.get("state")
        or ""
    )
    status = _normalizar_status_envio(status)
    if message_id:
        update_outbound_message(
            message_id,
            provider_status=status,
            remote_jid=remote_jid or None,
            provider_raw=item,
        )
        return True
    return False

