@app.route("/webhook", methods=["POST"])
def webhook():
    try:
        data = request.json or {}
        event = data.get("event","")
        event_norm = str(event or "").strip().lower().replace("_", ".")

        if event_norm in {"messages.update", "send.message", "message.update", "messages.status"}:
            payload = data.get("data")
            if isinstance(payload, list):
                for item in payload:
                    _atualizar_status_rastreio(item if isinstance(item, dict) else {})
            elif isinstance(payload, dict):
                _atualizar_status_rastreio(payload)
            return jsonify({"ok": True})

        if event_norm not in ("messages.upsert", "messages.upsert"):
            return jsonify({"ok": True})

        msg_data = data.get("data", {})
        key = msg_data.get("key", {})

        if key.get("fromMe", False):
            _atualizar_status_rastreio(msg_data)
            return jsonify({"ok": True})

        jid   = key.get("remoteJid","")
        nome  = msg_data.get("pushName","") or ""
        msg_obj = msg_data.get("message") or {}
        texto = (msg_obj.get("conversation") or
                 msg_obj.get("extendedTextMessage",{}).get("text") or "")

        if not texto or not jid or "@g.us" in jid:
            return jsonify({"ok": True})

        numero = jid.replace("@s.whatsapp.net","")
        mark_responded_by_phone(numero)

        ai = get_ai_settings()
        if not ai.get("ativo"): return jsonify({"ok": True})

        groq_key = ai.get("groq_api_key","") or GROQ_API_KEY
        if not groq_key: return jsonify({"ok": True})

        conv = get_or_create_conversation(jid, nome)
        historico = json.loads(conv.get("historico_json","[]"))

        # Modo humano ativo â€” nÃ£o responde automaticamente
        if conv.get("modo_humano"):
            return jsonify({"ok": True})

        # Checa transferÃªncia manual
        if checar_transferencia(texto):
            set_modo_humano(jid, True)
            msg_transfer = ("Claro! Vou chamar o AndrÃ© pra vocÃª agora ðŸ˜Š\n"
                           "WhatsApp dele: https://wa.me/5531982450904")
            send_text_message(numero, msg_transfer, typing=True)
            historico.append({"role":"user","content":texto})
            historico.append({"role":"assistant","content":msg_transfer})
            update_conversation(jid, historico, modo_humano=True)
            return jsonify({"ok": True})

        from services.groq_ai import (
            classificar_estagio,
            classificar_opcao_retorno,
            get_horas_reabertura,
            get_msg_abertura,
            get_msg_reabertura,
            is_inativo,
            is_numero_novo,
            mensagem_assistente_eh_reabertura,
        )

        # NÃºmero novo â€” envia boas-vindas E processa a mensagem
        if is_numero_novo(conv):
            msg_abertura = get_msg_abertura(nome, numero, historico)
            send_text_message(numero, msg_abertura, typing=True)
            # Salva boas-vindas e mensagem do cliente corretamente
            historico.append({"role":"assistant","content":msg_abertura})
            historico.append({"role":"user","content":texto})
            update_conversation(jid, historico)
            # Se o cliente jÃ¡ veio com intenÃ§Ã£o clara, responde em seguida
            if len(texto.split()) > 3:
                import time; time.sleep(2)
                prompt_extra = ai.get("prompt_sistema","")
                resposta = gerar_resposta(
                    texto,
                    historico,
                    groq_key,
                    prompt_extra,
                    nome_cliente=nome,
                    palavras_humano=ai.get("palavras_humano", ""),
                )
                if "##HUMANO##" in resposta:
                    set_modo_humano(jid, True)
                    resposta = "Perfeito! JÃ¡ passo pro AndrÃ© te atender ðŸ˜Š https://wa.me/5531982450904"
                send_text_message(numero, resposta, typing=True)
                historico.append({"role":"assistant","content":resposta})
                update_conversation(jid, historico)
            return jsonify({"ok": True})

        estagio_contexto = classificar_estagio(texto, historico)
        horas_reabertura = max(1, int(get_horas_reabertura(24)))
        ultima_msg = conv.get("ultima_msg", "")
        horas_inativo = 0.0
        if ultima_msg:
            try:
                dt_ultima = datetime.fromisoformat(str(ultima_msg).replace("T", " ").split(".")[0])
                horas_inativo = (datetime.now() - dt_ultima).total_seconds() / 3600
            except Exception:
                horas_inativo = 0.0

        reabrir_menu = horas_inativo >= horas_reabertura
        fluxo_cotacao = estagio_contexto in {"interessado", "ja_possui_seguro", "caro", "vou_pensar", "pediu_valor", "informou_veiculo"}
        menu_reabertura = mensagem_assistente_eh_reabertura(historico)
        opcao_menu = classificar_opcao_retorno(texto) if menu_reabertura else None

        # Se o menu de retorno ja foi enviado e o lead respondeu com uma opcao, trata o atalho
        if menu_reabertura and opcao_menu:
            historico.append({"role": "user", "content": texto})

            if opcao_menu == "assistencia":
                resposta = "📞 Assistência 24h:\n0800 940 2511"
                send_text_message(numero, resposta, typing=True)
                historico.append({"role": "assistant", "content": resposta})
                update_conversation(jid, historico)
                return jsonify({"ok": True, "reabertura": True, "opcao": "assistencia"})

            if opcao_menu == "consultor":
                set_modo_humano(jid, True)
                resposta = "Perfeito 😊\nUm consultor irá falar com você em breve."
                send_text_message(numero, resposta, typing=True)
                historico.append({"role": "assistant", "content": resposta})
                update_conversation(jid, historico, modo_humano=True)
                return jsonify({"ok": True, "reabertura": True, "opcao": "consultor"})

            if opcao_menu == "cotacao":
                resposta = (
                    f"Perfeito, {nome or 'voce'}.\n"
                    "Me manda modelo, ano e versao do carro que eu ja confiro a FIPE."
                ).strip()
                send_text_message(numero, resposta, typing=True)
                historico.append({"role": "assistant", "content": resposta})
                update_conversation(jid, historico)
                return jsonify({"ok": True, "reabertura": True, "opcao": "cotacao"})

            # Dúvidas no menu de retorno continua pelo fluxo da IA
            prompt_extra = ai.get("prompt_sistema", "")
            prompt_extra = (
                f"{prompt_extra}\n"
                "O lead escolheu duvidas no menu de reabertura. Responda curto, humano e consultivo, "
                "sem repetir o menu inteiro."
            ).strip()
            resposta = gerar_resposta(
                texto,
                historico,
                groq_key,
                prompt_extra,
                nome_cliente=nome,
                palavras_humano=ai.get("palavras_humano", ""),
            )
            if "##HUMANO##" in resposta:
                set_modo_humano(jid, True)
                resposta = "Perfeito! Vou passar pro Andre agora mesmo 🙂 https://wa.me/5531982450904"
            send_text_message(numero, resposta, typing=True)
            historico.append({"role": "assistant", "content": resposta})
            update_conversation(jid, historico)
            return jsonify({"ok": True, "reabertura": True, "opcao": "duvidas"})

        if reabrir_menu:
            # Lead voltou depois de um tempo: se ainda estiver em fluxo de cotacao, continua
            if fluxo_cotacao:
                historico.append({"role": "user", "content": texto})
                prompt_extra = ai.get("prompt_sistema", "")
                prompt_extra = (
                    f"{prompt_extra}\n"
                    "O lead voltou depois de um tempo e ja existia contexto de cotacao. Responda primeiro ao contexto atual "
                    "da conversa, sem repetir menu de boas-vindas. Depois ofereca ajuda de forma curta e natural."
                ).strip()
                resposta = gerar_resposta(
                    texto,
                    historico,
                    groq_key,
                    prompt_extra,
                    nome_cliente=nome,
                    palavras_humano=ai.get("palavras_humano", ""),
                )
                if "##HUMANO##" in resposta:
                    set_modo_humano(jid, True)
                    resposta = "Perfeito! Vou passar pro Andre agora mesmo 🙂 https://wa.me/5531982450904"
                send_text_message(numero, resposta, typing=True)
                historico.append({"role": "assistant", "content": resposta})
                update_conversation(jid, historico)
                return jsonify({"ok": True, "reabertura": True, "fluxo": "cotacao"})

            # Lead parado: reabre com menu humanizado
            msg_reabertura = get_msg_reabertura(nome, numero, historico)
            send_text_message(numero, msg_reabertura, typing=True)
            historico.append({"role": "assistant", "content": msg_reabertura})
            historico.append({"role": "user", "content": texto})
            update_conversation(jid, historico)
            return jsonify({"ok": True, "reabertura": True, "menu": True})

        # Fluxo normal â€” IA responde
        historico.append({"role":"user","content":texto})
        prompt_extra = ai.get("prompt_sistema","")
        resposta = gerar_resposta(
            texto,
            historico,
            groq_key,
            prompt_extra,
            nome_cliente=nome,
            palavras_humano=ai.get("palavras_humano", ""),
        )

        # IA pediu transferÃªncia
        if "##HUMANO##" in resposta:
            set_modo_humano(jid, True)
            resposta = "Perfeito! Vou passar pro AndrÃ© agora mesmo ðŸ˜Š https://wa.me/5531982450904"
            send_text_message(numero, resposta, typing=True)
            historico.append({"role":"assistant","content":resposta})
            update_conversation(jid, historico, modo_humano=True)
            return jsonify({"ok": True})

        send_text_message(numero, resposta, typing=True)
        historico.append({"role":"assistant","content":resposta})

        # Verifica se tem dados suficientes para gerar cotaÃ§Ã£o automÃ¡tica
        # (sÃ³ gera se a mensagem do cliente menciona modelo+ano e pede cotaÃ§Ã£o/proposta/valor)
        palavras_cotacao = ["cotacao", "cotaÃ§Ã£o", "valor", "proposta", "mensalidade",
                           "quanto", "custa", "preco", "preÃ§o", "cota"]
        pede_cotacao = any(p in texto.lower() for p in palavras_cotacao)

        if pede_cotacao:
            from services.groq_ai import deve_calcular_cotacao, gerar_cotacao_automatica
            if deve_calcular_cotacao(historico):
                import time as _t; _t.sleep(1.5)
                proposta = gerar_cotacao_automatica(historico, nome)
                if proposta:
                    send_text_message(numero, proposta, typing=True)
                    historico.append({"role":"assistant","content":proposta})

        # MantÃ©m histÃ³rico das Ãºltimas 30 mensagens
        if len(historico) > 30:
            historico = historico[-30:]
        update_conversation(jid, historico)

    except Exception as e:
        print(f"WEBHOOK ERRO: {e}")
        import traceback; traceback.print_exc()

    return jsonify({"ok": True})


