# â”€â”€ Follow-up automÃ¡tico â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
import threading as _threading

def _rodar_followups():
    """Thread que verifica clientes inativos e envia follow-up."""
    import time as _time
    from services.groq_ai import get_msg_reengajamento

    while True:
        try:
            _time.sleep(3600)  # verifica a cada hora
            ai = get_ai_settings()
            if not ai.get("ativo") or not (ai.get("groq_api_key") or GROQ_API_KEY):
                continue

            convs = list_conversations_ai()
            agora = datetime.now()

            for conv in convs:
                if conv.get("modo_humano"):
                    continue
                ultima = conv.get("ultima_msg","")
                if not ultima:
                    continue
                try:
                    dt = datetime.fromisoformat(ultima.replace("T"," ").split(".")[0])
                    horas = (agora - dt).total_seconds() / 3600
                    hist = json.loads(conv.get("historico_json","[]"))
                    if not hist:
                        continue
                    ultima_msg = hist[-1]
                    # SÃ³ faz follow-up se a Ãºltima mensagem foi do bot (cliente sumiu)
                    if ultima_msg.get("role") != "assistant":
                        continue
                    # Follow-up em 24h e 48h
                    numero = conv.get("jid","").replace("@s.whatsapp.net","")
                    nome = conv.get("nome","")
                    if 23 <= horas <= 25:  # janela 24h
                        msg = get_msg_reengajamento(nome, numero, hist)
                        send_text_message(numero, msg, typing=True)
                        hist.append({"role":"assistant","content":msg})
                        update_conversation(conv["jid"], hist)
                except Exception:
                    continue
        except Exception as e:
            print(f"Follow-up erro: {e}")

# Inicia thread de follow-up
_ft = _threading.Thread(target=_rodar_followups, daemon=True)
_ft.start()


@app.route("/api/fipe/consultar", methods=["POST"])
def api_fipe():
    """Consulta FIPE manualmente pelo painel."""
    d = request.json or {}
    placa = (d.get("placa", "") or "").strip()
    marca_id = (d.get("marca_id", "") or "").strip()
    modelo_id = (d.get("modelo_id", "") or "").strip()
    ano_codigo = (d.get("ano_codigo", "") or "").strip()
    marca = (d.get("marca", "") or "").strip()
    modelo = (d.get("modelo", "") or "").strip()
    versao = d.get("versao", "")
    ano = int(d.get("ano", 2020))
    categoria = d.get("categoria", "passeio")

    try:
        from services.fipe_service import (
            consultar_fipe_por_ids,
            consultar_veiculo_por_placa,
            extrair_valor_numerico,
            calcular_mensalidade,
            calcular_cota,
            montar_proposta_texto,
            COTA_PARTICIPACAO,
            obter_produtos_inclusos,
            validar_placa,
            buscar_marcas,
            buscar_modelos,
            buscar_anos,
        )
        tipo = "motos" if categoria == "moto" else "carros"
        if placa:
            if not validar_placa(placa):
                return jsonify({"erro": "Placa invalida. Use ABC1234 ou ABC1D23."}), 400
            resultado = consultar_veiculo_por_placa(placa, categoria=categoria)
            if not resultado:
                return jsonify({"erro": "Nao foi possivel consultar a placa. Verifique a placa e tente novamente."}), 404
        else:
            if marca_id and modelo_id and ano_codigo:
                resultado = consultar_fipe_por_ids(marca_id, modelo_id, ano_codigo, tipo)
            elif marca and modelo and ano:
                return jsonify({"erro": "A busca manual agora usa seletores controlados. Escolha marca, modelo e ano na lista."}), 400
            else:
                return jsonify({"erro": "Informe a placa ou use os seletores da busca manual."}), 400

        if not resultado:
            return jsonify({"erro": "Veiculo nao encontrado na tabela FIPE"}), 404

        valor = float(resultado.get("ValorNumerico") or extrair_valor_numerico(resultado.get("Valor", "0")))
        if valor <= 0:
            return jsonify({"erro": "Nao foi possivel calcular: valor FIPE zerado."}), 404
        if not resultado.get("CodigoFipe"):
            return jsonify({"erro": "Nao foi possivel calcular: codigo FIPE ausente."}), 404
        mensalidade = calcular_mensalidade(valor, categoria)
        cota = calcular_cota(valor, categoria)
        cota_pct = COTA_PARTICIPACAO.get(categoria.lower(), 5)
        produtos_inclusos = obter_produtos_inclusos(categoria)
        proposta_texto = montar_proposta_texto(
            d.get("nome", "voce"),
            resultado.get("Marca", marca or ""),
            resultado.get("Modelo", modelo or ""),
            int(resultado.get("AnoModelo", ano) or ano),
            valor,
            categoria,
            versao=resultado.get("Versao", versao),
            produtos_inclusos=produtos_inclusos,
        )

        return jsonify({
            "sucesso": True,
            "marca": resultado.get("Marca"),
            "modelo": resultado.get("Modelo"),
            "versao": resultado.get("Versao", versao),
            "ano": resultado.get("AnoModelo"),
            "placa": resultado.get("Placa", placa),
            "codigo_fipe": resultado.get("CodigoFipe"),
            "valor_fipe": valor,
            "valor_fipe_fmt": resultado.get("Valor"),
            "mensalidade": mensalidade,
            "cota_pct": cota_pct,
            "cota_valor": cota,
            "categoria": categoria,
            "produtos_inclusos": produtos_inclusos,
            "proposta_texto": proposta_texto,
        })
    except Exception as e:
        return jsonify({"erro": str(e)}), 500


